bad = []
cache = {}
for i, p, off, ln in rows:
    if p not in cache:
        try:
            cache[p] = open(p, 'rb')
        except Exception as e:
            bad.append((i, p, off, ln, 'open: %s' % e)); continue
    f = cache[p]; f.seek(off); b = f.read(ln)
    try:
        json.loads(b)
    except Exception as e:
        bad.append((i, p, off, ln, str(e)[:80]))
print("pointers", len(rows), "bad", len(bad))
for b in bad[:20]: print(b)
PY

